{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/charts",
  "data": [
    {
      "name": "data",
      "type": "Record<string, unknown>[]",
      "description": "Rows to visualize. Each row may contain the x field and one or more series fields.",
      "required": true
    },
    {
      "name": "xKey",
      "type": "string",
      "description": "Field name read from each data row for the shared x scale.",
      "required": true
    },
    {
      "name": "series",
      "type": "SeriesDef[]",
      "description": "Mark definitions created by helpers such as bar(), line(), area(), or dot(). Build a fresh array for each Chart.",
      "required": true
    },
    {
      "name": "height",
      "type": "number",
      "description": "Chart height in CSS pixels.",
      "default": "300"
    },
    {
      "name": "margin",
      "type": "Partial<ChartMargin>",
      "description": "Plot inset overrides in CSS pixels for top, right, bottom, and left.",
      "default": "{top: 24, right: 24, bottom: 32, left: 48}"
    },
    {
      "name": "yBaseline",
      "type": "'auto' | 'zero' | 'data'",
      "description": "How Chart derives the y-domain when yDomain is omitted: mark-aware zero/headroom, symmetric around zero, or tight to the data extent.",
      "default": "'auto'"
    },
    {
      "name": "yDomain",
      "type": "[number, number]",
      "description": "Explicit y-domain. When set, it takes precedence over yBaseline, automatic headroom, and scale nicening."
    },
    {
      "name": "xDomain",
      "type": "[number, number]",
      "description": "Explicit x-domain for numeric scales, including an empty streaming window. Categorical scales ignore it."
    },
    {
      "name": "grid",
      "type": "ReactNode",
      "description": "Grid content rendered behind the series, normally ChartGrid.",
      "slotElements": [
        {
          "__element": "ChartGrid",
          "props": {
            "horizontal": true
          }
        }
      ]
    },
    {
      "name": "axes",
      "type": "ReactNode",
      "description": "Axis content rendered after the series, normally one or more ChartAxis elements.",
      "slotElements": [
        {
          "__element": "ChartAxis",
          "props": {
            "position": "bottom"
          }
        },
        {
          "__element": "ChartAxis",
          "props": {
            "position": "left"
          }
        }
      ]
    },
    {
      "name": "legend",
      "type": "boolean | ChartLegendProps",
      "description": "Set true for a derived bottom legend, or pass items, position, and alignment.",
      "default": "false"
    },
    {
      "name": "tooltip",
      "type": "boolean | Omit<ChartTooltipProps, 'series'>",
      "description": "Set true for the grouped pointer tooltip, or pass render and presentation options.",
      "default": "false"
    },
    {
      "name": "interactions",
      "type": "ReactNode",
      "description": "Interaction overlays rendered above the pointer-capture layer."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Additional SVG content rendered after the built-in tooltip for advanced composition."
    },
    {
      "name": "title",
      "type": "string",
      "description": "Visible heading and accessible name for the chart image. A localized fallback is derived when omitted."
    },
    {
      "name": "subtitle",
      "type": "string",
      "description": "Visible supporting text that also describes the chart image."
    },
    {
      "name": "ref",
      "type": "Ref<HTMLDivElement>",
      "description": "Ref forwarded to the root chart container."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    },
    {
      "name": "className",
      "type": "string",
      "description": "CSS class name appended to the root chart container."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles merged onto the root chart container after the component styles."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
